"""File to house all functions related to interfacing with Chart UI area of the Mosaiq Application"""

import warnings
from .objects.mosaiq_chart_objects import Chart
from .objects.mosaiq_d_and_i_objects import DandI
from interops.libraries.squish_actions import CommonActions
from .d_and_i import click_treatment_promote_button
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME
from interops.libraries.squish_actions.exceptions import FailedToFindObject

def __find_main_chart_dashboard_container() -> bool:
    """Searches for main dashboard container object within the Chart UI. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the chart.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Chart._main_chart_dashboard_container) is not None else False

