@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_diagnosis_and_problems_tab_item() -> None:
    """Locates the Charts Dashboard Container > then clicks the Diagnosis and Problems Tab Item and waits for the UI to load.
    """
    if __find_main_chart_dashboard_container():
        CommonActions.left_click_object(Chart.diagnosis_and_problems_Tab)
        CommonActions.find_object(Chart.diagnosis_and_problems_Container)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_diagnoses_and_problems_grid_object() -> None:
    """Locates the Diagnoses and Problems Tab Window > then clicks the grid object.
    """
    if __find_chart_diagnoses_and_problems_window():
        CommonActions.left_click_object(Chart.diagnosis_and_Problems_Grid)

