@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_tx_plans_promote_plan_button() -> None:
    """Locates the TX Plans Tab Window > then clicks the Promote Plan button within the RT Plan Details UI object,
    and waits for Promote Treatment Plan UI appears.
    """
    if __find_chart_tx_plans_plan_details_container():
        CommonActions.left_click_object(Chart.rt_Plan_Details_Promote_Button)
        CommonActions.find_object(DandI.promotePlan_Main_Dialog)

def click_treatment_plan_promote_button() -> None:
    """Locates the Promote Treatment Plan dialog > clicks the Promote button > then waits for promote treatment plan UI to disappear
    """
    click_treatment_promote_button()

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_tx_plans_treatment_fields_tab_item() -> None:
    """Locates the Plan Details container of the Tx Plans tab of the Chart UI > then navigates the internal tab section over
    to the Treatment Fields UI.
    """
    if __find_chart_tx_plans_plan_details_container():
        CommonActions.left_click_object(Chart.tx_Plans_Treatment_Fields_TabItem)
        CommonActions.find_object(Chart.treatment_Fields_Related_Treatment_Fields_Grid)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def does_plan_exist_in_plan_browser(planName: str) -> bool: # type: ignore
    """Locates the TX Plans Plan Browse grid object > searches the Plan Browser grid for the given planName > returns a True/False value if plan is found.

    :return: True or False
    :rtype: bool
    """
    try:
        if __find_chart_tx_plans_plan_browse_container():
            plans = CommonActions.get_child_objects(Chart.tx_Plans_Plan_Browse_Data_Panel_Container)
            if CommonActions.get_child_object_by_value(plans, planName) is None:
                return False
            return True
    except FailedToFindObject as e:
        warnings.warn(f"Tx Plans plan browse container wasn't visible when expected to be. \n {e}", RuntimeWarning)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_plan_browse_refresh_button() -> None:
    """Locates the TX Plans Plan Browse grid object > clicks the Refresh button on the Plan Browser toolbar.
    """
    if __find_chart_tx_plans_plan_browse_container():
        CommonActions.left_click_object(Chart.tx_Plans_Toolbar_Refresh_Button)